from concurrent.futures import ThreadPoolExecutor

_pool=ThreadPoolExecutor(max_workers=12)

def one(a):
 k,n,p=a
 return AESGCM(k).encrypt(n,p,None)
class Solver:
 def solve(self,p,**kw):
  data=p['plaintext']; n=p['nonce']; k=p['key']; N=len(data); q=((N+11)//12+15)//16*16
  args=[]
  base=int.from_bytes(n[-4:],'big')
  for s in range(0,N,q):
